{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7]. Standard bench and clinical research approaches alone are not well suited to account for this complexity, as most cancer control interventions often focus on explicit, often linear health outcomes of a specific, well-defined population [1, 8, 9]. ... Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The introduction describes the current state of knowledge about cancer complexity, limitations of standard approaches, the growth of system dynamics in public health, and explicitly states that application to cancer prevention and control has not been studied, identifying an important uncertainty/gap."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "In a 2019 report, the National Academies of Sciences, Engineering, and Medicine argued that systems science methods could help illustrate the multilevel nature of cancer effects and costs to society and help cancer control efforts be more agile and adaptive [7]. The Journal of the National Cancer Institute published several reports calling for the use of complex, multilevel, or systems-focused approaches to advance the landscape of cancer prevention and control [1, 2, 10]. ... Systems models, particularly well calibrated simulation models, provide a relatively lowcost and low-risk opportunity for comparing potential interventions or treatments in silico before involving busy clinics and patients in trials [1, 7, 11, 12]. ... The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The text cites authoritative calls for systems approaches, explains benefits of systems models, and explicitly notes the lack of study of system dynamics in cancer prevention/control, justifying the importance and need for this review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The manuscript notes past reviews about system dynamics generally but does not identify, cite, or discuss any similar systematic reviews specific to system dynamics applications in cancer or explain the need in relation to prior systematic reviews; no explicit statement comparing to or updating prior similar reviews is provided."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "A formal research protocol was not created for this review. The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "This item applies to reviews of intervention effects. The authors state this is a methods review that did not assess health outcomes, so describing a mechanism of action for interventions is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "The suggestion to consider a logic model applies to reviews of complex interventions or delivery contexts; because this review is a methods review of system dynamics modeling (not an effects review of interventions), inclusion of a logic model is not applicable."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "System dynamics modeling, which consists of diagramming and simulation approaches for understanding and managing such complexity, is being increasingly applied to cancer prevention and control, but the breadth, characteristics, and quality of these studies is not known. We searched PubMed, Scopus, APA PsycInfo, and eight peer-reviewed journals to identify cancer-related studies that used system dynamics modeling. A dual review process was used to determine eligibility. Included studies were assessed using quality criteria adapted from prior literature and mapped onto the cancer control continuum. Characteristics of studies and models were abstracted and qualitatively synthesized.",
      "reason": "The review explicitly states its objectives to identify and describe the breadth, characteristics, and quality of system dynamics studies applied to cancer prevention and control (objectives and approach are stated). However, the objectives are not presented using a formal question-formulation framework (e.g., PICO, PICOS, or a structured review question), so the requirement to use a relevant question-formulation framework is not met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "A formal research protocol was not created for this review. The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "This element applies to reviews of intervention effects requiring PICO-style planned comparisons. The authors state this was a methods review that did not assess health outcomes, so the PICO-style planned comparisons requirement does not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "The manuscript explicitly lists the study characteristics used to determine eligibility, including publication type (peer-reviewed), language (English), eligible study designs/approaches (types of system dynamics modeling), topical scope (cancer prevention or control), and a follow-up/time restriction (published within the last 10 years)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; ... and 4) were published within the last 10 years.",
      "reason": "The review specifies eligibility criteria for report characteristics: publication status (peer-reviewed journals), language (English), and a time/dissemination year restriction (published within the last 10 years)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found distinguishing exclusion due to outcomes not being measured from exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "As shown in Fig 1, most studies included a computational system dynamics simulation model (n = 21; 66%), while the remaining studies (n = 11; 34%) used only diagramming approaches (referred to as diagram-only studies in this review).",
      "reason": "The review specifies groups used in the synthesis (simulation vs diagram-only) and provides counts for each group; these groupings are used throughout the results and analyses (e.g., comparisons of quality and purposes by model type)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This search period was selected to reflect recent developments and current applications of system dynamics modeling related to cancer.",
      "reason": "The authors provide a rationale for the notable restriction on study eligibility (limiting to the last 10 years) explaining it was chosen to reflect recent developments and current applications; additional acknowledgment of this bounding is discussed in the Limitations (text_20)."
    }
  ],
  "confidence": 75
}

